import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Behavioral tests for {@link PointUtil}.
 *
 * <p>The expected coordinates are expressed in PDF points.  Dimensions such as
 * 25.4 mm deliberately map to 72 pt, which keeps the expectations readable and
 * independent of the conversion implementation.</p>
 */
class PointUtilTests {

    private static final double EPS = 0.001;

    @Test
    void convertPathAbbreviatedDataParsesEverySupportedCommand() {
        List<PathPoint> points = PointUtil.convertPathAbbreviatedDatatoPoint(
                "M 1 2 L 3 4 C S 5 6 B 7 8 9 10 11 12 "
                        + "Q 13 14 15 16 A 17 18 19 20 21 22 23");

        assertEquals(7, points.size());

        assertPoint(points.get(0), "M", 1, 2, 0, 0, 0, 0);
        assertPoint(points.get(1), "L", 3, 4, 0, 0, 0, 0);
        assertPoint(points.get(2), "C", 0, 0, 0, 0, 0, 0);
        assertPoint(points.get(3), "S", 5, 6, 0, 0, 0, 0);
        assertPoint(points.get(4), "B", 7, 8, 9, 10, 11, 12);
        assertPoint(points.get(5), "Q", 13, 14, 15, 16, 0, 0);

        PathPoint arc = points.get(6);
        assertEquals("A", arc.type);
        assertFloat(17, arc.rx);
        assertFloat(18, arc.ry);
        assertFloat(19, arc.rotation);
        assertFloat(20, arc.arc);
        assertFloat(21, arc.sweep);
        assertFloat(22, arc.x);
        assertFloat(23, arc.y);
    }

    @Test
    void convertPathAbbreviatedDataHandlesEmptyUnknownAndMalformedInput() {
        assertTrue(PointUtil.convertPathAbbreviatedDatatoPoint(null).isEmpty());
        assertTrue(PointUtil.convertPathAbbreviatedDatatoPoint("").isEmpty());
        assertTrue(PointUtil.convertPathAbbreviatedDatatoPoint("CM 1 2").isEmpty());

        List<PathPoint> malformed = PointUtil.convertPathAbbreviatedDatatoPoint("M not-a-number 9");
        assertEquals(1, malformed.size());
        assertPoint(malformed.get(0), "M", 0, 9, 0, 0, 0, 0);
    }

    @Test
    void calPathPointConvertsSupportedCommandsInPlace() {
        PathPoint move = new PathPoint("M", 25.4f, 12.7f, 0, 0, 0, 0);
        PathPoint line = new PathPoint("L", 12.7f, 25.4f, 0, 0, 0, 0);
        PathPoint close = new PathPoint("C", 0, 0, 0, 0, 0, 0);
        PathPoint start = new PathPoint("S", 0, 0, 0, 0, 0, 0);
        PathPoint cubic = new PathPoint("B", 1, 2, 3, 4, 5, 6);
        PathPoint quadratic = new PathPoint("Q", 1, 2, 3, 4, 5, 6);
        PathPoint arc = new PathPoint("A", 1, 2, 3, 4, 5, 6, 7);

        List<PathPoint> result = PointUtil.calPathPoint(Arrays.asList(
                move, line, close, start, cubic, quadratic, arc));

        assertEquals(5, result.size());
        assertFloat(72, move.x1);
        assertFloat(36, move.y1);
        assertFloat(36, line.x1);
        assertFloat(72, line.y1);
        assertFloat(0, close.x1);
        assertFloat(0, close.y1);
        assertFloat(0, start.x1);
        assertFloat(0, start.y1);
        assertPoint(result.get(4), "B", 2.8346457, 5.6692913,
                8.503937, 11.3385827, 14.1732283, 17.007874);
        assertSame(move, result.get(0));
        assertSame(line, result.get(1));
        assertSame(close, result.get(2));
        assertSame(start, result.get(3));
    }

    @Test
    void calTextPointAdvancesEachCharacterByItsDelta() {
        TextCode first = new TextCode()
                .setCoordinate(25.4, 12.7)
                .setContent("AB")
                .setDeltaX(2.54)
                .setDeltaY(1.27);
        TextCode second = new TextCode()
                .setCoordinate(0d, 0d)
                .setContent("Z");

        List<TextCodePoint> points = PointUtil.calTextPoint(Arrays.asList(first, second));

        assertEquals(3, points.size());
        assertTextPoint(points.get(0), 72, 36, "A");
        assertTextPoint(points.get(1), 79.2, 39.6, "B");
        assertTextPoint(points.get(2), 0, 0, "Z");
    }

    @Test
    void calTextPointKeepsCharactersAtOriginWhenDeltaIsAbsent() {
        TextCode code = new TextCode()
                .setCoordinate(25.4, 12.7)
                .setContent("AB");

        List<TextCodePoint> points = PointUtil.calTextPoint(Collections.singletonList(code));

        assertEquals(2, points.size());
        assertTextPoint(points.get(0), 72, 36, "A");
        assertTextPoint(points.get(1), 72, 36, "B");
        assertTrue(PointUtil.calTextPoint(Collections.singletonList(
                new TextCode().setCoordinate(0d, 0d).setContent(""))).isEmpty());
    }

    @Test
    void adjustPosAddsOnlyBoundaryOriginAndDoesNotClamp() {
        double[] unchanged = PointUtil.adjustPos(100, 200, -5, 300, null);
        assertArrayEquals(new double[]{-5, 300}, unchanged, EPS);

        ST_Box boundary = new ST_Box(10, 20, 30, 40);
        double[] adjusted = PointUtil.adjustPos(30, 40, 50, -2, boundary);
        assertArrayEquals(new double[]{60, 18}, adjusted, EPS);
    }

    @Test
    void combineBoundaryComposesOriginsAndKeepsChildSize() {
        ST_Box parent = new ST_Box(10, 20, 100, 200);
        ST_Box child = new ST_Box(3, 4, 30, 40);

        ST_Box combined = PointUtil.combineBoundary(parent, child);
        assertEquals(13, combined.getTopLeftX(), EPS);
        assertEquals(24, combined.getTopLeftY(), EPS);
        assertEquals(30, combined.getWidth(), EPS);
        assertEquals(40, combined.getHeight(), EPS);

        assertSame(child, PointUtil.combineBoundary(null, child));
        assertSame(parent, PointUtil.combineBoundary(parent, null));
        assertNull(PointUtil.combineBoundary(null, null));
    }

    @Test
    void ctmCalPointAppliesTheTwoDimensionalAffineTransform() {
        Double[] ctm = new Double[]{2d, 3d, -1d, 4d, 10d, 20d};

        double[] result = PointUtil.ctmCalPoint(1, 2, ctm);

        assertArrayEquals(new double[]{10, 31}, result, EPS);
        assertArrayEquals(new double[]{7, 9},
                PointUtil.ctmCalPoint(7, 9, new Double[]{1d, 0d, 0d, 1d, 0d, 0d}), EPS);
    }

    @Test
    void isLegacyAbsolutePathRequiresAllContext() {
        ST_Box boundary = new ST_Box(0, 0, 100, 100);
        ST_Array identity = new ST_Array(1, 0, 0, 1, 0, 0);
        List<PathPoint> points = Collections.singletonList(
                new PathPoint("M", 1000, 1000, 0, 0, 0, 0));

        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, null, points, true, identity));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, points, false, identity));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, points, true, null));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, null, true, identity));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary,
                Collections.emptyList(), true, identity));

        List<PathPoint> small = Collections.singletonList(
                new PathPoint("M", 100, 100, 0, 0, 0, 0));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, small, true, identity));
    }

    @Test
    void isLegacyAbsolutePathDetectsCoordinatesThatFitAfterLegacyDpiScaling() {
        ST_Box boundary = new ST_Box(0, 0, 210, 297);
        ST_Array identity = new ST_Array(1, 0, 0, 1, 0, 0);
        List<PathPoint> points = Collections.singletonList(
                new PathPoint("M", 2500, 2500, 0, 0, 0, 0));

        assertTrue(PointUtil.isLegacyAbsolutePath(210, 297, boundary, points, true, identity));
    }

    @Test
    void isLegacyAbsolutePathRejectsPathsAlreadyInsideTheBoundaryAfterCtm() {
        ST_Box boundary = new ST_Box(0, 0, 100, 100);
        ST_Array scaleDown = new ST_Array(0.05, 0, 0, 0.05, 0, 0);
        List<PathPoint> points = Collections.singletonList(
                new PathPoint("M", 1000, 1000, 0, 0, 0, 0));

        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, points, true, scaleDown));
