    @Test
    void isLegacyAbsolutePathRejectsCoordinatesStillOutsideAfterLegacyScaling() {
        ST_Box boundary = new ST_Box(0, 0, 100, 100);
        ST_Array identity = new ST_Array(1, 0, 0, 1, 0, 0);
        List<PathPoint> points = Collections.singletonList(
                new PathPoint("M", 10000, 10000, 0, 0, 0, 0));

        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, points, true, identity));
    }

    @Test
    void isLegacyAbsolutePathAccountsForCurveAndArcControlPoints() {
        ST_Box boundary = new ST_Box(0, 0, 210, 297);
        ST_Array identity = new ST_Array(1, 0, 0, 1, 0, 0);
        List<PathPoint> points = Arrays.asList(
                new PathPoint("B", 2500, 2500, 2501, 2501, 2502, 2502),
                new PathPoint("Q", 2500, 2500, 2502, 2502, 0, 0),
                new PathPoint("A", 1, 1, 0, 0, 1, 2500, 2500));

        assertTrue(PointUtil.isLegacyAbsolutePath(210, 297, boundary, points, true, identity));
    }

    @Test
    void calPdfPathLineWidthAppliesScaleAndCtm() {
        assertEquals(10, PointUtil.calPdfPathLineWidth(
                5, 2, true, new ST_Array(100, 100, 100, 100, 0, 0)), EPS);
        assertEquals(144, PointUtil.calPdfPathLineWidth(25.4, 2, false, null), EPS);
        assertEquals(360, PointUtil.calPdfPathLineWidth(
                25.4, 1, false, new ST_Array(3, 4, 4, 3, 100, 100)), EPS);
    }

    @Test
    void calPdfPathPointConvertsSimpleCommandsAndReversesYForPdf() {
        List<PathPoint> input = Arrays.asList(
                new PathPoint("M", 12.7f, 25.4f, 0, 0, 0, 0),
                new PathPoint("L", 38.1f, 50.8f, 0, 0, 0, 0),
                new PathPoint("C", 0, 0, 0, 0, 0, 0));

        List<PathPoint> result = PointUtil.calPdfPathPoint(
                101.6, 101.6, null, input, false, null, null, null, true);

        assertEquals(3, result.size());
        assertPoint(result.get(0), "M", 36, 216, 0, 0, 0, 0);
        assertPoint(result.get(1), "L", 108, 144, 0, 0, 0, 0);
        assertPoint(result.get(2), "C", 0, 288, 0, 0, 0, 0);
        assertSame(input.get(0), result.get(0));
    }

    @Test
    void calPdfPathPointCombinesCtmBoundaryAndScale() {
        List<PathPoint> input = Collections.singletonList(
                new PathPoint("M", 12.7f, 7.62f, 0, 0, 0, 0));
        ST_Box boundary = new ST_Box(5.08, 2.54, 50.8, 25.4);
        ST_Array ctm = new ST_Array(1, 0, 0, 1, 2.54, 1.27);

        List<PathPoint> result = PointUtil.calPdfPathPoint(
                50.8, 25.4, boundary, input, true, ctm, null, null, false, 2.0);

        assertPoint(result.get(0), "M", 100.8, 57.6, 0, 0, 0, 0);
    }

    @Test
    void calPdfPathPointConvertsCubicQuadraticAndArcCommands() {
        List<PathPoint> input = Arrays.asList(
                new PathPoint("B", 12.7f, 25.4f, 38.1f, 50.8f, 63.5f, 76.2f),
                new PathPoint("Q", 12.7f, 25.4f, 38.1f, 50.8f, 0, 0),
                new PathPoint("A", 12.7f, 25.4f, 30f, 60f, 1f, 38.1f, 50.8f));

        List<PathPoint> result = PointUtil.calPdfPathPoint(
                101.6, 101.6, null, input, false, null, null, null, true);

        assertEquals(3, result.size());
        assertPoint(result.get(0), "B", 36, 216, 108, 144, 180, 72);
        assertPoint(result.get(1), "Q", 36, 216, 108, 144, 0, 0);

        PathPoint arc = result.get(2);
        assertEquals("A", arc.type);
        assertFloat(36, arc.rx);
        assertFloat(72, arc.ry);
        assertFloat(30, arc.rotation);
        assertFloat(60, arc.arc);
        assertFloat(1, arc.sweep);
        assertFloat(108, arc.x);
        assertFloat(144, arc.y);
    }

    @Test
    void calPdfPathPointAppliesCompositeCtmAndBoundary() {
        List<PathPoint> input = Collections.singletonList(
                new PathPoint("M", 12.7f, 12.7f, 0, 0, 0, 0));
        ST_Box compositeBoundary = new ST_Box(25.4, 25.4, 50.8, 50.8);
        ST_Array compositeCtm = new ST_Array(2, 0, 0, 2, 0, 0);

        List<PathPoint> result = PointUtil.calPdfPathPoint(
                101.6, 101.6, null, input, false, null,
                compositeBoundary, compositeCtm, false);

        assertPoint(result.get(0), "M", 144, 144, 0, 0, 0, 0);
    }

    @Test
    void calPdfPathPointUsesLegacyAbsolutePathCoordinatesInsteadOfCtmAndBoundary() {
        ST_Box boundary = new ST_Box(0, 0, 210, 297);
        ST_Array identity = new ST_Array(1, 0, 0, 1, 0, 0);

        List<PathPoint> withoutOriginFix = PointUtil.calPdfPathPoint(
                210, 297, boundary,
                Collections.singletonList(new PathPoint("M", 2500, 2500, 0, 0, 0, 0)),
                true, identity, null, null, false);
        assertPoint(withoutOriginFix.get(0), "M", 600, 600, 0, 0, 0, 0);

        List<PathPoint> withOriginFix = PointUtil.calPdfPathPoint(
                210, 297, boundary,
                Collections.singletonList(new PathPoint("M", 2500, 2500, 0, 0, 0, 0)),
                true, identity, null, null, true);
        assertPoint(withOriginFix.get(0), "M", 600, 241.89, 0, 0, 0, 0);
    }

    @Test
    void calPdfTextCoordinateTransformsOriginOnceAndDeltasAsVectors() {
        TextCode code = new TextCode()
                .setCoordinate(12.7, 12.7)
                .setContent("AB")
                .setDeltaX(2.54)
                .setDeltaY(1.27);
        ST_Array ctm = new ST_Array(2, 0, 0, 3, 5.08, 2.54);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                50.8, 50.8, null, 12f, Collections.singletonList(code),
                true, ctm, false, 1.0);

        assertEquals(2, points.size());
        assertTextPoint(points.get(0), 86.4, 115.2, "A");
        assertTextPoint(points.get(1), 100.8, 126.0, "B");
    }

    @Test
    void calPdfTextCoordinateUsesZeroForMissingCoordinatesAndAppliesBoundaryScale() {
        TextCode code = new TextCode().setContent("A");
        ST_Box boundary = new ST_Box(5.08, 2.54, 50.8, 50.8);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
