                false, null, false, 2.0);

        assertEquals(1, points.size());
        assertTextPoint(points.get(0), 14.4, 7.2, "A");
    }

    @Test
    void calPdfTextCoordinateDecodesEntitiesAndDropsCopyrightAndNewlines() {
        TextCode code = new TextCode()
                .setCoordinate(0d, 0d)
                .setContent("&lt;A&gt;&amp;\n&nbsp;&quot;&copy;&apos;");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                50.8, 50.8, null, 12f, Collections.singletonList(code),
                false, null, false, 1.0);

        StringBuilder decoded = new StringBuilder();
        for (TextCodePoint point : points) {
            decoded.append(point.getText());
        }
        assertEquals("<A>& \"'", decoded.toString());
        assertEquals(7, points.size());
    }

    @Test
    void calPdfTextCoordinateOverloadAppliesDeltaXAndDeltaY() {
        TextCode code = new TextCode()
                .setCoordinate(12.7, 25.4)
                .setContent("AB")
                .setDeltaX(2.54)
                .setDeltaY(1.27);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                101.6, 101.6, null, 12f, Collections.singletonList(code),
                new ArrayList<CT_CGTransform>(), null, null,
                false, null, true, 1.0);

        assertEquals(2, points.size());
        assertTextPoint(points.get(0), 36, 216, "A");
        assertTextPoint(points.get(1), 43.2, 212.4, "B");
    }

    @Test
    void calPdfTextCoordinateOverloadAppliesCtmTranslationOnlyToTheOrigin() {
        TextCode code = new TextCode()
                .setCoordinate(12.7, 12.7)
                .setContent("AB")
                .setDeltaX(2.54)
                .setDeltaY(1.27);
        ST_Array ctm = new ST_Array(2, 0, 0, 3, 5.08, 2.54);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                50.8, 50.8, null, 12f, Collections.singletonList(code),
                new ArrayList<CT_CGTransform>(), null, null,
                true, ctm, false, 1.0);

        assertTextPoint(points.get(0), 86.4, 115.2, "A");
        assertTextPoint(points.get(1), 100.8, 126.0, "B");
    }

    @Test
    void calPdfTextCoordinateOverloadMapsGlyphsFromCgTransforms() {
        TextCode code = new TextCode()
                .setCoordinate(12.7, 12.7)
                .setContent("AB");
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(2)
                .setGlyphCount(2)
                .setGlyphs(new ST_Array("10", "20"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                50.8, 50.8, null, 12f, Collections.singletonList(code),
                Collections.singletonList(transform), null, null,
                false, null, false, 1.0);

        assertEquals(2, points.size());
        assertTextPoint(points.get(0), 36, 36, "A");
        assertTextPoint(points.get(1), 36, 36, "B");
        assertEquals("10", points.get(0).getGlyph());
        assertEquals("20", points.get(1).getGlyph());
    }

    @Test
    void calPdfTextCoordinateOverloadSkipsPositionsConsumedByGlyphTransforms() {
        TextCode code = new TextCode()
                .setCoordinate(0d, 0d)
                .setContent("ABC")
                .setDeltaX(1d, 2d);
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(3)
                .setGlyphCount(2)
                .setGlyphs(new ST_Array("9", "8"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                50.8, 50.8, null, 12f, Collections.singletonList(code),
                Collections.singletonList(transform), null, null,
                false, null, false, 1.0);

        assertEquals(3, points.size());
        assertTextPoint(points.get(0), 0, 0, "A");
        assertTextPoint(points.get(1), 0, 0, "");
        assertTextPoint(points.get(2), 0, 0, "");
        assertEquals("9", points.get(0).getGlyph());
        assertEquals("8", points.get(1).getGlyph());
        assertNull(points.get(2).getGlyph());
    }

    @Test
    void calPdfTextCoordinateOverloadAppliesCompositeCtmAfterLocalPositioning() {
        TextCode code = new TextCode()
                .setCoordinate(12.7, 12.7)
                .setContent("A");
        ST_Array compositeCtm = new ST_Array(1, 0, 0, 1, 12.7, 12.7);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                101.6, 101.6, null, 12f, Collections.singletonList(code),
                new ArrayList<CT_CGTransform>(), null, compositeCtm,
                false, null, false, 1.0);

        assertEquals(1, points.size());
        assertTextPoint(points.get(0), 72, 72, "A");
    }

    private static void assertPoint(PathPoint point, String type,
                                    double x1, double y1,
                                    double x2, double y2,
                                    double x3, double y3) {
        assertEquals(type, point.type);
        assertFloat(x1, point.x1);
        assertFloat(y1, point.y1);
        assertFloat(x2, point.x2);
        assertFloat(y2, point.y2);
        assertFloat(x3, point.x3);
        assertFloat(y3, point.y3);
    }

    private static void assertTextPoint(TextCodePoint point, double x, double y, String text) {
        assertEquals(x, point.getX(), EPS);
        assertEquals(y, point.getY(), EPS);
        assertEquals(text, point.getText());
    }

    private static void assertFloat(double expected, double actual) {
        assertEquals(expected, actual, EPS);
    }
}

