        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, null, true, identity));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary,
                Collections.emptyList(), true, identity));

        List<PathPoint> small = Collections.singletonList(
                new PathPoint("M", 100, 100, 0, 0, 0, 0));
        assertFalse(PointUtil.isLegacyAbsolutePath(100, 100, boundary, small, true, identity));
    }

