    private static void assertPoint(PathPoint point, String type,
                                    double x1, double y1,
                                    double x2, double y2,
                                    double x3, double y3) {
        assertEquals(type, point.type);
        assertFloat(x1, point.x1);
        assertFloat(y1, point.y1);
        assertFloat(x2, point.x2);
        assertFloat(y2, point.y2);
        assertFloat(x3, point.x3);
        assertFloat(y3, point.y3);
    }

    private static void assertTextPoint(TextCodePoint point, double x, double y, String text) {
        assertEquals(x, point.getX(), EPS);
        assertEquals(y, point.getY(), EPS);
        assertEquals(text, point.getText());
    }

    private static void assertFloat(double expected, double actual) {
        assertEquals(expected, actual, EPS);
    }
